<?php
declare(strict_types=1); namespace Comfino\Common\Backend\Payment\ProductTypeFilter; use Comfino\Common\Backend\Payment\ProductTypeFilterInterface; use Comfino\Common\Shop\Cart; use Comfino\Common\Shop\Product\CategoryFilter; class FilterByExcludedCategory implements ProductTypeFilterInterface{ private $categoryFilter; private $excludedCategoryIdsByProductType; public function __construct(CategoryFilter $categoryFilter,array$excludedCategoryIdsByProductType){$this->categoryFilter=$categoryFilter;$this->excludedCategoryIdsByProductType=$excludedCategoryIdsByProductType;} public function getAllowedProductTypes($availableProductTypes,$cart):array{$allowedProductTypes=[]; foreach($availableProductTypes as $productType){if(array_key_exists((string)$productType,$this->excludedCategoryIdsByProductType)){if($this->categoryFilter->isCartValid($cart,$this->excludedCategoryIdsByProductType[(string)$productType])){$allowedProductTypes[]=$productType;}}else{$allowedProductTypes[]=$productType;}}return $allowedProductTypes;}public function getAsArray():array{return['excludedCategoryIdsByProductType'=>$this->excludedCategoryIdsByProductType];}}